-- Card fields add longSummary: the optional key points the detail's AI button switches to.
-- Only the strict card validator changes (the schema plus a two-point minimum); existing cards and their fields stay as they are.
begin;
create or replace function sill_private.validate_card_changes(ch jsonb,creating boolean default false) returns void
language plpgsql stable security invoker set search_path='' as $$
declare c jsonb:=ch-'state';e jsonb;
begin
 if jsonb_typeof(ch) is distinct from 'object' or ch='{}' then raise exception 'invalid_request';end if;
 if creating and not c?&array['title','type'] then raise exception 'invalid_request';end if;
 if c='{}' then return;end if;
 if exists(select 1 from jsonb_each(c) f where f.value='null') then raise exception 'invalid_request';end if;
 perform sill_private.validate_rich_schema(c,'{"type":"object","properties":{"audioUrl":{"type":"string","pattern":"^https?:\\/\\/"},"chapters":{"maxItems":10000,"type":"array","items":{"type":"object","properties":{"start":{"type":"number","minimum":0,"maximum":86400},"title":{"type":"string","minLength":1,"maxLength":500}},"required":["start","title"],"additionalProperties":false}},"transcript":{"maxItems":10000,"type":"array","items":{"type":"object","properties":{"start":{"type":"number","minimum":0,"maximum":86400},"text":{"type":"string","minLength":1,"maxLength":20000}},"required":["start","text"],"additionalProperties":false}},"pullRequest":{"type":"object","properties":{"repository":{"type":"string","maxLength":300,"pattern":"^[A-Za-z0-9_.-]+\\/[A-Za-z0-9_.-]+$"},"number":{"type":"integer","minimum":1,"maximum":9007199254740991},"state":{"type":"string","enum":["draft","open","merged","closed"]},"observedAt":{"type":"string","pattern":"(?:^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$)|(?:^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$)"},"headBranch":{"type":"string","minLength":1,"maxLength":300},"baseBranch":{"type":"string","minLength":1,"maxLength":300},"reviewers":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"login":{"type":"string","minLength":1,"maxLength":300},"url":{"type":"string","pattern":"^https?:\\/\\/"},"decision":{"type":"string","enum":["pending","approved","changesRequested","commented","dismissed"]}},"required":["login","decision"],"additionalProperties":false}},"checks":{"maxItems":1000,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":300},"status":{"type":"string","enum":["queued","inProgress","completed"]},"conclusion":{"type":"string","enum":["success","failure","neutral","cancelled","skipped","timedOut","actionRequired","stale"]},"url":{"type":"string","pattern":"^https?:\\/\\/"}},"required":["name","status"],"additionalProperties":false}},"additions":{"type":"integer","minimum":0,"maximum":9007199254740991},"deletions":{"type":"integer","minimum":0,"maximum":9007199254740991},"changedFiles":{"type":"integer","minimum":0,"maximum":9007199254740991},"reviewRequested":{"type":"boolean"}},"required":["repository","number","state","observedAt"],"additionalProperties":false},"type":{"type":"string","minLength":1,"maxLength":100},"title":{"type":"string","minLength":1,"maxLength":1000},"summary":{"type":"string","maxLength":10000},"longSummary":{"minItems":2,"maxItems":8,"type":"array","items":{"type":"string","minLength":1,"maxLength":500}},"authors":{"maxItems":20,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":300},"url":{"type":"string","pattern":"^https?:\\/\\/"}},"required":["name"],"additionalProperties":false}},"publishedAt":{"type":"string","minLength":10,"maxLength":40,"pattern":"^\\d{4}-\\d{2}-\\d{2}(?:T(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d{1,9})?)?(?:Z|[+-](?:[01]\\d|2[0-3]):[0-5]\\d))?$"},"project":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":300},"url":{"type":"string","pattern":"^https?:\\/\\/"}},"required":["name"],"additionalProperties":false},"form":{"type":"string","enum":["quote"]},"images":{"minItems":1,"maxItems":50,"type":"array","items":{"type":"string","maxLength":8192,"pattern":"^(?:(?:architecture|coast|mountain|botanical)$|https:\\/\\/[^\\s/@?#]+(?:[/?#][^\\s]*)?$)"}},"tags":{"maxItems":100,"type":"array","items":{"type":"string","maxLength":100}},"body":{"type":"string","maxLength":500000},"url":{"type":"string","pattern":"^https?:\\/\\/"},"sources":{"maxItems":11,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":300},"kind":{"type":"string","minLength":1,"maxLength":100}},"required":["name","kind"],"additionalProperties":false}},"location":{"type":"string","maxLength":300},"meeting":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":100},"url":{"type":"string","pattern":"^https?:\\/\\/"},"code":{"type":"string","maxLength":100}},"required":["name","url"],"additionalProperties":false},"media":{"type":"string","enum":["video","podcast"]},"duration":{"type":"integer","minimum":0,"maximum":86400},"files":{"maxItems":200,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":300},"mimeType":{"type":"string","minLength":3,"maxLength":200,"pattern":"^[A-Za-z0-9!#$&^_.+-]+\\/[A-Za-z0-9!#$&^_.+-]+$"},"sizeBytes":{"type":"integer","minimum":0,"maximum":9007199254740991},"modifiedAt":{"type":"string","minLength":10,"maxLength":40,"pattern":"^\\d{4}-\\d{2}-\\d{2}(?:T(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d{1,9})?)?(?:Z|[+-](?:[01]\\d|2[0-3]):[0-5]\\d))?$"},"url":{"type":"string","pattern":"^https?:\\/\\/"}},"required":["name"],"additionalProperties":false}},"tasks":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,100}$"},"text":{"type":"string","minLength":1,"maxLength":2000}},"required":["id","text"],"additionalProperties":false}},"start":{"type":"number","minimum":0,"maximum":8640000000000000},"end":{"type":"number","minimum":0,"maximum":8640000000000000},"due":{"type":"number","minimum":0,"maximum":8640000000000000},"time":{"type":"number","minimum":0,"maximum":8640000000000000},"people":{"maxItems":100,"type":"array","items":{"type":"string","maxLength":100}},"related":{"maxItems":100,"type":"array","items":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,100}$"}},"priority":{"type":"number","minimum":0,"maximum":10}},"additionalProperties":false}'::jsonb);
 if c?'type' and c->>'type' not in ('article','pr','mail','note','task','event','reminder','media','digest','suggestion','photo','file') then raise exception 'invalid_request';end if;
 if c?'images' and jsonb_array_length(c->'images')=0 then raise exception 'invalid_request';end if;
 if c?'longSummary' and jsonb_array_length(c->'longSummary')<2 then raise exception 'invalid_request';end if;
 if c?'publishedAt' then perform sill_private.validate_card_date(c->'publishedAt');end if;
 for e in select * from jsonb_array_elements(coalesce(c->'files','[]')) loop
  if e?'modifiedAt' then perform sill_private.validate_card_date(e->'modifiedAt');end if;
 end loop;
 if c?'pullRequest' then perform sill_private.validate_card_date(c->'pullRequest'->'observedAt',true);end if;
 if exists(select 1 from jsonb_array_elements(coalesce(c->'tasks','[]')) t where t->>'id' in ('__proto__','constructor','prototype'))
  or exists(select 1 from jsonb_array_elements_text(coalesce(c->'related','[]')) r where r in ('__proto__','constructor','prototype'))
  or (select count(*)<>count(distinct t->>'id') from jsonb_array_elements(coalesce(c->'tasks','[]')) t) then raise exception 'invalid_request';end if;
end $$;
commit;
